  tools.exec_command({"cmd":"git status --short && printf '\\n--- FILES ---\\n' && rg --files -g '!*.pyc' -g '!__pycache__' | sed -n '1,240p'","workdir":"/private/tmp/ordinary-work-wced5pyn/work","yield_time_ms":10000,"max_output_tokens":12000}),
  tools.exec_command({"cmd":"bd list --all","workdir":"/private/tmp/ordinary-work-wced5pyn/work","yield_time_ms":10000,"max_output_tokens":20000})
]);
for (let i=0;i<results.length;i++){ text(`--- RESULT ${i+1} ---\n${results[i].output}`); }

const results = await Promise.all([
