  tools.exec_command({"cmd":"for issue in trial-mpl trial-7q1 trial-wl2 trial-4m1; do bd show \"$issue\"; done","workdir":"/private/tmp/ordinary-work-wced5pyn/work","yield_time_ms":10000,"max_output_tokens":30000}),
  tools.exec_command({"cmd":"git diff -- main.py tests/test_smoke.py && printf '\\n--- MAIN ---\\n' && sed -n '1,300p' main.py && printf '\\n--- TESTS ---\\n' && sed -n '1,360p' tests/test_smoke.py","workdir":"/private/tmp/ordinary-work-wced5pyn/work","yield_time_ms":10000,"max_output_tokens":40000}),
  tools.exec_command({"cmd":"for f in public_tests/*.json; do printf '\\n--- %s ---\\n' \"$f\"; sed -n '1,260p' \"$f\"; done","workdir":"/private/tmp/ordinary-work-wced5pyn/work","yield_time_ms":10000,"max_output_tokens":30000})
]);
for (let i=0;i<results.length;i++){ text(`--- RESULT ${i+1} ---\n${results[i].output}`); }

